{
    int a = 0; 

    if (dest == '\0' || src == '\0')
        return (0);
    for (a = 0; src[a] != '\0'; a++) {
        if (a < n) {
            dest[a] = src[a];
            if (src[a] == '\0')
                a = n;
        }
    }
    return (dest);
}

